-- Seed dashboard issues as public reports so they can be followed persistently.
-- These rows use UUID primary keys generated by Supabase while keeping the
-- dashboard IDs in external_id, e.g. GC-2026-05434.

drop policy if exists "Anyone can view public reports" on public.reports;
create policy "Anyone can view public reports"
  on public.reports for select using (user_id is null);

insert into public.reports (
  user_id,
  external_id,
  title,
  category,
  tag,
  district,
  status,
  description,
  address,
  assigned_to,
  estimated_resolution,
  report_count,
  photo_count,
  location_main,
  location_sub,
  merged,
  pin,
  timeline,
  created_at,
  updated_at
